mapper.select:
SELECT COUNT(*)
FROM event
WHERE event_name=#{eventName}

mapper.update:
UPDATE event SET
	event_name 			= #{eventName}
	,event_stat_ty_cd 	= #{eventStatTyCd}
	,event_ty_cd	 	= #{eventTyCd}
	,dscnt 				= #{dscnt}
	,start_time 		= #{startTime}
	,end_time 			= #{endTime}
WHERE
	event_id 			= #{eventId}
